<map version="1.0.1"><node CREATED="1747229405869" ID="ID_root" MODIFIED="1747229405869" TEXT="GNU编译工具集"><node CREATED="1747229405869" ID="ID_eb67a8b8a5a3dafd" POSITION="right" MODIFIED="1747229405869" TEXT="编译工具"><node CREATED="1747229405869" ID="ID_7ba8f4e9b2271f62" MODIFIED="1747229405869" TEXT="预处理"><node CREATED="1747229405869" ID="ID_43093f9b0290eb6e" MODIFIED="1747229405869" TEXT="gcc -E hello.c -o hello.i&amp;lt;br&amp;gt;"></node><node CREATED="1747229405869" ID="ID_9ead384a41201d12" MODIFIED="1747229405869" TEXT="-E&amp;nbsp;相当于告诉gcc，&amp;nbsp;只执行预处理步骤"></node><node CREATED="1747229405869" ID="ID_8e4f1da430fc6c14" MODIFIED="1747229405869" TEXT="-o&amp;nbsp;相当于告诉它，生成一个文件。&amp;nbsp;不要往屏幕上做打印"></node></node><node CREATED="1747229405869" ID="ID_602449f92e3c3322" MODIFIED="1747229405869" TEXT="编译"><node CREATED="1747229405869" ID="ID_8af7e7777867989b" MODIFIED="1747229405869" TEXT="gcc -S hello.i/hello.c -o hello.s"></node><node CREATED="1747229405869" ID="ID_a87e948f7cbe07ee" MODIFIED="1747229405869" TEXT="会生成一个汇编代码，我们不需要会汇编代码。知道有这个过程"></node></node><node CREATED="1747229405869" ID="ID_a8077ae619bf37e0" MODIFIED="1747229405869" TEXT="汇编"><node CREATED="1747229405870" ID="ID_bd612554e190cba1" MODIFIED="1747229405870" TEXT="gcc -c hello.s -o hello.o"></node><node CREATED="1747229405870" ID="ID_d4c86fc746d64518" MODIFIED="1747229405870" TEXT="会生成机器指令。&amp;nbsp;这时候会生成二进制的数据，人很难看懂"></node><node CREATED="1747229405870" ID="ID_8bfbf86ca177a9b2" MODIFIED="1747229405870" TEXT="得到机器指令之后，其实是二进制。&amp;nbsp;我们想看看二进制是什么东西，可以将其转换为16进制"><node CREATED="1747229405870" ID="ID_5c1fd48ae0f9ed1a" MODIFIED="1747229405870" TEXT=":%!xxd"></node><node CREATED="1747229405870" ID="ID_11bfc1d77c81ff39" MODIFIED="1747229405870" TEXT=":%!xxd -r"></node><node CREATED="1747229405870" ID="ID_1f1b9ef921cd2ed3" MODIFIED="1747229405870" TEXT="或者可以直接使用xxd&amp;nbsp;文件名来查看&amp;lt;br&amp;gt;"></node></node></node><node CREATED="1747229405870" ID="ID_f072be46622aaad7" MODIFIED="1747229405870" TEXT="链接过程指令"><node CREATED="1747229405870" ID="ID_4c098f24fa826c13" MODIFIED="1747229405870" TEXT="gcc test1.c //&amp;nbsp;没有指定可执行程序的名称，会生成一个 a.out的可执行程序&amp;lt;br&amp;gt;gcc test1.c -o test1&amp;lt;br&amp;gt;"></node><node CREATED="1747229405870" ID="ID_ffe4e9a4e0e749c0" MODIFIED="1747229405870" TEXT="如果想多个文件链接到一起。&amp;nbsp;只用将多个文件，同时放到gcc&amp;nbsp;后面&amp;lt;br&amp;gt;gcc test2.c test222.c -o test2&amp;lt;br&amp;gt;最终，会将多个.c&amp;nbsp;变成一个可执行程序。"></node></node><node CREATED="1747229405870" ID="ID_b38d9e22f8f50eea" MODIFIED="1747229405870" TEXT="其他的选项"><node CREATED="1747229405870" ID="ID_2cea350ef4ec6f03" MODIFIED="1747229405870" TEXT="-Wall&amp;nbsp;会打印出所有的警告信息。建议大家加上&amp;nbsp;"><node CREATED="1747229405870" ID="ID_a700dd71cbaaa17b" MODIFIED="1747229405870" TEXT="warning"></node><node CREATED="1747229405870" ID="ID_930a5d48056d1233" MODIFIED="1747229405870" TEXT="error"></node></node><node CREATED="1747229405870" ID="ID_10fd05bf32ffec6b" MODIFIED="1747229405870" TEXT="-O0,-O1,-O2,-O3编译器优化级别："><node CREATED="1747229405870" ID="ID_1bc12c5bd609f3d7" MODIFIED="1747229405870" TEXT="编译器会帮你优化你的代码"></node><node CREATED="1747229405870" ID="ID_fde37a71f7de4130" MODIFIED="1747229405870" TEXT="编译器的优化，会进行一些同义替换。&amp;nbsp;但是在debug的时候，我们不希望它进行优化。&amp;nbsp;"></node><node CREATED="1747229405870" ID="ID_8d15cc8f8c595025" MODIFIED="1747229405870" TEXT="-O0&amp;nbsp;不优化，&amp;nbsp;在debug的，会选这个。&amp;nbsp;"></node></node><node CREATED="1747229405870" ID="ID_c443bceb6e7caaf0" MODIFIED="1747229405870" TEXT="-g：&amp;nbsp;调试的时候使用，&amp;nbsp;像一些变量名在编译的过程中会被丢掉，可以通过-g告诉编译器，帮我保留。我还要使用的&amp;lt;br&amp;gt;"></node></node><node CREATED="1747229405870" ID="ID_afc855200db837ef" MODIFIED="1747229405870" TEXT="条件编译"><node CREATED="1747229405870" ID="ID_3382ab9023d08261" MODIFIED="1747229405870" TEXT="在有一些环境中，我们希望打印的越多越好。&amp;nbsp;比如调试的时候。&amp;nbsp;"></node><node CREATED="1747229405870" ID="ID_e7096ddea2226863" MODIFIED="1747229405870" TEXT="但是在最后调试完成之后，代码需要放到真实的生产环境上运行时候。&amp;nbsp;"></node><node CREATED="1747229405870" ID="ID_2842a84a1db794b7" MODIFIED="1747229405870" TEXT="条件编译：&amp;nbsp;就是控制，在有一些环境的时候加上。&amp;nbsp;有一些环境的时候别加这段代码"></node><node CREATED="1747229405870" ID="ID_2445051886280dae" MODIFIED="1747229405870" TEXT="在项目要上线的前夕，应该尽量保证代码不要动。&amp;nbsp;"></node><node CREATED="1747229405870" ID="ID_af8b88c9ce0c7b09" MODIFIED="1747229405870" TEXT="语法"><node CREATED="1747229405870" ID="ID_142a1c4b5f8601ab" MODIFIED="1747229405870" TEXT="语法不难"></node><node CREATED="1747229405870" ID="ID_b3e24a69093fbbd1" MODIFIED="1747229405870" TEXT="难得是干啥的&amp;lt;br&amp;gt;"></node></node></node></node><node CREATED="1747229405870" ID="ID_6496f24590acac22" POSITION="right" MODIFIED="1747229405870" TEXT="GDB调试"><node CREATED="1747229405870" ID="ID_7abb45e3922b1c2a" MODIFIED="1747229405870" TEXT="GDB是一个在Linux下调试的程序。&amp;nbsp;我们可以使用GDB来调试我们的代码。&amp;lt;br&amp;gt;它里面也有类似VS中的各种调试功能，但是都是使用命令来完成的"></node><node CREATED="1747229405870" ID="ID_49279682e4de2bd2" MODIFIED="1747229405870" TEXT="安装GDB"></node><node CREATED="1747229405870" ID="ID_29902d38f771d0d4" MODIFIED="1747229405870" TEXT="生成带调试信息的可执行程序指令"><node CREATED="1747229405870" ID="ID_f9832238db4e806c" MODIFIED="1747229405870" TEXT="gcc hello.c -o hello -g -O0 -Wall&amp;lt;br&amp;gt;"></node><node CREATED="1747229405870" ID="ID_ee1ab58b14a82d34" MODIFIED="1747229405870" TEXT="-g&amp;nbsp; -Wall -O0&amp;nbsp;的含义要知道"></node></node><node CREATED="1747229405870" ID="ID_01bf7147f52fde73" MODIFIED="1747229405870" TEXT="进入GDB"><node CREATED="1747229405870" ID="ID_679b24f0fde315de" MODIFIED="1747229405870" TEXT="方式1： gdb&amp;nbsp; 文件名"></node><node CREATED="1747229405870" ID="ID_4a8d8d9c601c95a5" MODIFIED="1747229405870" TEXT="方式2：&amp;nbsp;&amp;lt;br&amp;gt;gdb&amp;nbsp;&amp;lt;br&amp;gt;file test1"></node></node><node CREATED="1747229405870" ID="ID_ca6b6ea59f64a6d1" MODIFIED="1747229405870" TEXT="正式的操作"><node CREATED="1747229405870" ID="ID_5c477f0bdf57dba9" MODIFIED="1747229405870" TEXT="list/l"><node CREATED="1747229405870" ID="ID_e3fad3ac61bbbd31" MODIFIED="1747229405870" TEXT="显示代码。&amp;nbsp;看一下打断点的位置"></node><node CREATED="1747229405870" ID="ID_8587b3884d18590d" MODIFIED="1747229405870" TEXT="l&amp;nbsp;就是查看源代码，默认就是往下翻"></node><node CREATED="1747229405870" ID="ID_332c438971cc7ab8" MODIFIED="1747229405870" TEXT="l -&amp;nbsp;就是上翻"></node><node CREATED="1747229405870" ID="ID_0555f620a5920b92" MODIFIED="1747229405870" TEXT="l&amp;nbsp;行号"></node><node CREATED="1747229405870" ID="ID_34a8a84717ee0f4f" MODIFIED="1747229405870" TEXT="l&amp;nbsp;文件名:行号：&amp;nbsp;在多个.c生成的可执行程序中，可以使用这个固定看哪个文件的多少行"></node></node><node CREATED="1747229405870" ID="ID_b189d0643ebccc36" MODIFIED="1747229405870" TEXT="一些散命令"><node CREATED="1747229405870" ID="ID_fb140725c34c275a" MODIFIED="1747229405870" TEXT="run/r :&amp;nbsp;启动程序。&amp;nbsp;这里就是以debug模式启动"></node><node CREATED="1747229405870" ID="ID_c2550472b5de3d29" MODIFIED="1747229405870" TEXT="kill/k :&amp;nbsp;终止调试。但是不会退出GDB"></node><node CREATED="1747229405870" ID="ID_4a3344cd295c9fac" MODIFIED="1747229405870" TEXT="quit/q:&amp;nbsp;退出gdb。&amp;nbsp;这时候调试肯定也退了"></node></node><node CREATED="1747229405870" ID="ID_26adbf5804f1743e" MODIFIED="1747229405870" TEXT="断点"><node CREATED="1747229405870" ID="ID_156849ace1aa5efa" MODIFIED="1747229405870" TEXT="打断点"><node CREATED="1747229405870" ID="ID_317e039c6bf74e5f" MODIFIED="1747229405870" TEXT="b&amp;nbsp;行号"></node><node CREATED="1747229405870" ID="ID_8a9296d754d607f3" MODIFIED="1747229405870" TEXT="b&amp;nbsp;文件名:行号"></node><node CREATED="1747229405870" ID="ID_f8bd3004564905d6" MODIFIED="1747229405870" TEXT="tb&amp;nbsp;临时断点。&amp;nbsp;这个断点只会有效一次，后续就会被直接删掉"></node><node CREATED="1747229405870" ID="ID_90ad498094fbf98d" MODIFIED="1747229405870" TEXT="break&amp;nbsp;"></node></node><node CREATED="1747229405870" ID="ID_81f06ab7cefa70ef" MODIFIED="1747229405870" TEXT="查看断点"><node CREATED="1747229405870" ID="ID_3d28d27b61a7a2e9" MODIFIED="1747229405870" TEXT="info break/ i b"></node><node CREATED="1747229405870" ID="ID_5e5ef38e6eabed23" MODIFIED="1747229405870" TEXT="展示的信息"><node CREATED="1747229405870" ID="ID_64d28a75b398482d" MODIFIED="1747229405870" TEXT="Num:&amp;nbsp;是一个唯一值。&amp;nbsp;会不断自增，即使你将断点删除，再建一个断点，也不会二次利用这个序号&amp;lt;br&amp;gt;所以，它是唯一的"></node><node CREATED="1747229405870" ID="ID_cb1ad20526008a0f" MODIFIED="1747229405870" TEXT="disp"><node CREATED="1747229405870" ID="ID_85115ef817d14eab" MODIFIED="1747229405870" TEXT="keep表示是持久断点&amp;lt;br&amp;gt;del表示是一次性断点"><node CREATED="1747229405870" ID="ID_e84172400194f34a" MODIFIED="1747229405870" TEXT="一次性断点。程序运行过一次断点之后。断点就会被删掉"></node></node></node><node CREATED="1747229405870" ID="ID_188cc43c36066a45" MODIFIED="1747229405870" TEXT="enb"><node CREATED="1747229405870" ID="ID_e204de158ebeddac" MODIFIED="1747229405870" TEXT="断点是否生效"></node></node><node CREATED="1747229405870" ID="ID_c1faf2951ac7b61d" MODIFIED="1747229405870" TEXT="what"><node CREATED="1747229405870" ID="ID_c555241986ee5a8c" MODIFIED="1747229405870" TEXT="断点在哪个位置"></node></node></node></node><node CREATED="1747229405870" ID="ID_98cf9f645afb6707" MODIFIED="1747229405870" TEXT="删除断点"><node CREATED="1747229405870" ID="ID_76c4f953bc517cd6" MODIFIED="1747229405870" TEXT="d [Num]：&amp;nbsp;输入的Num就是在info break的时候看到的"></node><node CREATED="1747229405870" ID="ID_3c8be2f2c9f16dec" MODIFIED="1747229405870" TEXT="d&amp;nbsp; &amp;nbsp;断点全删掉"></node></node><node CREATED="1747229405870" ID="ID_8c2dd3cf768affe0" MODIFIED="1747229405870" TEXT="运行"><node CREATED="1747229405870" ID="ID_3443fbf0f7f4ce50" MODIFIED="1747229405870" TEXT="step/s&amp;nbsp; ：&amp;nbsp;一步步执行，碰到函数会进入"><node CREATED="1747229405870" ID="ID_bcd02b0e08ff7c19" MODIFIED="1747229405870" TEXT="什么函数都会往里面进"></node></node><node CREATED="1747229405870" ID="ID_9ff4e0fa463d8298" MODIFIED="1747229405870" TEXT="next/n:&amp;nbsp;一步步执行，碰到函数不会进入&amp;lt;br&amp;gt;"><node CREATED="1747229405870" ID="ID_d2a1730b4d0b86d3" MODIFIED="1747229405870" TEXT="系统函数，建议用n。&amp;nbsp;比如像printf，如果使用s。进不去"></node></node><node CREATED="1747229405870" ID="ID_6c991d8f75caf152" MODIFIED="1747229405870" TEXT="c:&amp;nbsp;跳到下一次断点。&amp;nbsp;&amp;lt;br&amp;gt;"></node><node CREATED="1747229405870" ID="ID_e7268e6ba5039dff" MODIFIED="1747229405870" TEXT="finish/fin :&amp;nbsp;跳出函数，比如函数的执行过程比较复杂，现在想让函数直接结束。&amp;nbsp;"></node><node CREATED="1747229405870" ID="ID_8b6ffc1ea3ba915e" MODIFIED="1747229405870" TEXT="print/p express：&amp;nbsp;打印某个表达式的值。&amp;nbsp;&amp;lt;br&amp;gt;其实还可以使用这个来改变量的值。&amp;nbsp;&amp;lt;br&amp;gt;print num=10&amp;nbsp; 相当于在程序运行时来修改变量的值&amp;lt;br&amp;gt;"><node CREATED="1747229405870" ID="ID_b4a4ea97f75f00e7" MODIFIED="1747229405870" TEXT="print一般用来做输出。&amp;nbsp;也用的比较多"></node></node><node CREATED="1747229405870" ID="ID_db8681f666530db3" MODIFIED="1747229405870" TEXT="display/disp :&amp;nbsp;将一个表达式的值持续挂在输出上。&amp;nbsp;&amp;lt;br&amp;gt;undisplay/undisp :&amp;nbsp;取消持续的输出，注意这里的参数是编号&amp;lt;br&amp;gt;info disp:&amp;nbsp;查看有哪些持续的输出。&amp;nbsp;&amp;lt;br&amp;gt;"><node CREATED="1747229405870" ID="ID_15baddd5d7ca4f47" MODIFIED="1747229405870" TEXT="display：&amp;nbsp;也要注意一下。&amp;nbsp;"></node></node><node CREATED="1747229405870" ID="ID_96698a9a349cefad" MODIFIED="1747229405870" TEXT="info args:&amp;nbsp;输出参数&amp;lt;br&amp;gt;info locals:&amp;nbsp;输出局部变量"></node><node CREATED="1747229405870" ID="ID_009bd2c5e6987cb8" MODIFIED="1747229405870" TEXT="ignore N count :&amp;nbsp;跳过N号断点，count次。这个在循环的时候比较有用"></node><node CREATED="1747229405870" ID="ID_f610a567c0475f73" MODIFIED="1747229405870" TEXT="查看内存"></node></node><node CREATED="1747229405870" ID="ID_196292acd15dbdb8" MODIFIED="1747229405870" TEXT="其他的信息"><node CREATED="1747229405870" ID="ID_7327e4c3c375cd9e" MODIFIED="1747229405870" TEXT="bt:&amp;nbsp;显示函数调用栈"></node></node><node CREATED="1747229405870" ID="ID_67c0dd47d5cd8ad7" MODIFIED="1747229405870" TEXT="在平常的时候，可能需要传参"><node CREATED="1747229405870" ID="ID_3131e2c4d3f6d7c2" MODIFIED="1747229405870" TEXT="./test1 111 222 333&amp;nbsp;"></node><node CREATED="1747229405870" ID="ID_5cb902e7000338a5" MODIFIED="1747229405870" TEXT="在GDB运行的时候，如何传参。&amp;nbsp;&amp;lt;br&amp;gt;r&amp;nbsp;参数1&amp;nbsp; 参数2&amp;nbsp; 参数3&amp;nbsp;"></node></node></node></node></node><node CREATED="1747229405870" ID="ID_008f88e71a171105" POSITION="right" MODIFIED="1747229405870" TEXT="库文件"><node CREATED="1747229405870" ID="ID_4b19996178746678" MODIFIED="1747229405870" TEXT="什么是库文件"><node CREATED="1747229405870" ID="ID_c450e69bae0071e6" MODIFIED="1747229405870" TEXT="简单说，就是别人写好的轮子，我拿过来直接使用。"></node><node CREATED="1747229405870" ID="ID_aec67444d818e64d" MODIFIED="1747229405870" TEXT="库文件的分类：&amp;nbsp;静态库和动态库"></node></node><node CREATED="1747229405870" ID="ID_76472e19d5aca427" MODIFIED="1747229405870" TEXT="什么是静态库，什么是动态库"><node CREATED="1747229405870" ID="ID_505802140606cbb4" MODIFIED="1747229405870" TEXT="静态库就是在链接阶段就将程序的代码，整个整过去的库。&amp;nbsp;"></node><node CREATED="1747229405870" ID="ID_6892155ab5fb9a80" MODIFIED="1747229405870" TEXT="动态库就是只存待会去哪找。在链接阶段不会把别人的代码弄过来"></node><node CREATED="1747229405870" ID="ID_936b170cecaa7565" MODIFIED="1747229405870" TEXT="优缺点"><node CREATED="1747229405870" ID="ID_f4b66ba296ed9988" MODIFIED="1747229405870" TEXT="静态库"><node CREATED="1747229405870" ID="ID_05a24f843e9ca425" MODIFIED="1747229405870" TEXT="优点"><node CREATED="1747229405870" ID="ID_1c4c95aa3d359446" MODIFIED="1747229405870" TEXT="快"></node><node CREATED="1747229405870" ID="ID_7df715dfa87cbf7c" MODIFIED="1747229405870" TEXT="移植性强"></node></node><node CREATED="1747229405870" ID="ID_12191276d1364fe6" MODIFIED="1747229405870" TEXT="缺点"><node CREATED="1747229405870" ID="ID_0fc876b32ad2479e" MODIFIED="1747229405870" TEXT="生成的可执行程序大。&amp;nbsp;"></node><node CREATED="1747229405870" ID="ID_4382cbfbcfbf73c9" MODIFIED="1747229405870" TEXT="如果库进行了升级，所有依赖这个库的都需要重新链接"></node></node></node><node CREATED="1747229405870" ID="ID_fb0b07f00a0dd9da" MODIFIED="1747229405870" TEXT="动态库"><node CREATED="1747229405870" ID="ID_a4573b418eae9fe7" MODIFIED="1747229405870" TEXT="优点"><node CREATED="1747229405870" ID="ID_552b9790cc3de4a4" MODIFIED="1747229405870" TEXT="小。"></node><node CREATED="1747229405870" ID="ID_0bee5940d8180f9f" MODIFIED="1747229405870" TEXT="对于开发者和使用者友好。&amp;nbsp;升级了之后，使用者不需要重新进行链接。&amp;nbsp;"></node></node><node CREATED="1747229405870" ID="ID_7161b7e53beb6ff7" MODIFIED="1747229405870" TEXT="缺点"><node CREATED="1747229405870" ID="ID_a181c4ef1c1156a0" MODIFIED="1747229405870" TEXT="移植性不好。&amp;nbsp;"></node><node CREATED="1747229405870" ID="ID_c9aeb9bdae261896" MODIFIED="1747229405870" TEXT="速度会稍微慢一点"></node></node></node></node><node CREATED="1747229405870" ID="ID_6d4ab136be60f8d3" MODIFIED="1747229405870" TEXT="得知道根据优缺点，怎么去选动态库和静态库"><node CREATED="1747229405870" ID="ID_7e03a760114b4369" MODIFIED="1747229405870" TEXT="一般根据移植性、体积来选"></node><node CREATED="1747229405870" ID="ID_ee9462bf6e82e05a" MODIFIED="1747229405870" TEXT="要知道怎么选，但是一般自己选的概率不大"></node></node></node><node CREATED="1747229405870" ID="ID_81f1b775bab28523" MODIFIED="1747229405870" TEXT="生成静态库和动态库的指令"><node CREATED="1747229405870" ID="ID_98e95d88decbc7ba" MODIFIED="1747229405870" TEXT="看一看、练一练"></node><node CREATED="1747229405870" ID="ID_f00c10eb16c38cc0" MODIFIED="1747229405870" TEXT="下次碰到了查文档"></node></node></node><node CREATED="1747229405870" ID="ID_9aa956f4803fba2c" POSITION="right" MODIFIED="1747229405870" TEXT="Makefile"><node CREATED="1747229405870" ID="ID_8a0c074c77f56165" MODIFIED="1747229405870" TEXT="需要知道什么是Makefile"><node CREATED="1747229405870" ID="ID_6c44d2a388f56cc4" MODIFIED="1747229405870" TEXT="就是一个脚本，我们用来生成可执行程序的命令，可以放在这个脚本里。这样我们就不用每次都去写这个生成的命令。&amp;nbsp;&amp;lt;br&amp;gt;然后我们又想用这个命令。&amp;nbsp;"></node><node CREATED="1747229405870" ID="ID_7a3d8c273d1c5154" MODIFIED="1747229405870" TEXT="脚本就是文本。&amp;nbsp;这个文本可以直接运行"></node></node><node CREATED="1747229405870" ID="ID_21ddee267f53e9b3" MODIFIED="1747229405870" TEXT="Makefile的基本组成单元得知道"><node CREATED="1747229405870" ID="ID_af161d6333413b62" MODIFIED="1747229405870" TEXT="基本语法得知道"></node></node><node CREATED="1747229405870" ID="ID_805c198e12a27222" MODIFIED="1747229405870" TEXT="增量编译得知道"><node CREATED="1747229405870" ID="ID_4f33e0dc324c9b5f" MODIFIED="1747229405870" TEXT="代码如果经过了更改。&amp;nbsp;它会重新执行编译这个步骤，最终生成main.o."></node></node><node CREATED="1747229405870" ID="ID_1a3d2e5b655e065a" MODIFIED="1747229405870" TEXT="使用得知道"><node CREATED="1747229405870" ID="ID_80c4861acf635481" MODIFIED="1747229405870" TEXT="我给一个Makefile。&amp;nbsp;你要知道怎么使用"></node></node><node CREATED="1747229405870" ID="ID_7e14bca85ecb72c7" MODIFIED="1747229405870" TEXT="后续，我们的使用场景基本是怎样的？"><node CREATED="1747229405870" ID="ID_d4ac81ab2d0c5c3c" MODIFIED="1747229405870" TEXT="后续一般是这样的，我们写一个test1.c文件&amp;lt;br&amp;gt;gcc test1.c -o test1 -Wall -g&amp;nbsp;"></node><node CREATED="1747229405870" ID="ID_ad2ebfcf333d4a40" MODIFIED="1747229405870" TEXT="所以，我们给大家提供了一个通用的Makefile。&amp;nbsp;检查你这里面有哪些.c文件。&amp;nbsp;&amp;lt;br&amp;gt;然后将这些.c生成同名的&amp;nbsp;可执行程序。&amp;nbsp;&amp;lt;br&amp;gt;只要这些文件做了修改。&amp;nbsp;就增量编译&amp;lt;br&amp;gt;"></node><node CREATED="1747229405870" ID="ID_b874c028ec81ee70" MODIFIED="1747229405870" TEXT="通配符"></node><node CREATED="1747229405870" ID="ID_caea3f5b0136c339" MODIFIED="1747229405870" TEXT="test1.c---&amp;gt; test1&amp;lt;br&amp;gt;test2.c --&amp;gt; test2"></node></node><node CREATED="1747229405870" ID="ID_99f1c43eb8404842" MODIFIED="1747229405870" TEXT="Makefile的使用"><node CREATED="1747229405870" ID="ID_60ca409a6e00f67b" MODIFIED="1747229405870" TEXT="创建一个Makefile。然后将我们写好的东西放进去。&amp;nbsp;它就可以帮你完成编译、链接的功能&amp;lt;br&amp;gt;同时也可以删除，或者重新编译链接这些文件"></node><node CREATED="1747229405870" ID="ID_30bb1156d14a30ee" MODIFIED="1747229405870" TEXT="make"></node><node CREATED="1747229405870" ID="ID_fcc325d8ba9440b7" MODIFIED="1747229405870" TEXT="make&amp;nbsp;clean"></node><node CREATED="1747229405870" ID="ID_afde30fcb8c294f6" MODIFIED="1747229405870" TEXT="make rebuild"><node CREATED="1747229405870" ID="ID_4dd06557b3c7732a" MODIFIED="1747229405870" TEXT="先把之前生成的文件，全干掉"></node><node CREATED="1747229405870" ID="ID_4fb547e8166203b7" MODIFIED="1747229405870" TEXT="然后再重新生成一遍"></node></node><node CREATED="1747229405870" ID="ID_fab5e392b3e4829e" MODIFIED="1747229405870" TEXT="make buildagain&amp;lt;br&amp;gt;"></node></node><node CREATED="1747229405870" ID="ID_ae2ea9ed55f03865" MODIFIED="1747229405870" TEXT="工作过程中，一般写Makefile的机会不多。&amp;nbsp;"></node></node></node></map>